import {Updater} from './fm1ota.js';
import {productOf,logicalImage} from './fm1pkg.js';
import {BackupConnection,captureBackup,readBackup,restoreBackup} from './fm1backup.js';
const $=id=>document.getElementById(id);
const STOCK_SHA='db1642b2b6fa5c2cccb11ffd13878068bb28601678d3644049f99dc40e7edb8a';
let manifest,packs={},access,busy=false,connected=false,target='wolf',logLines=[];
let detected='',archive=null,stockEpoch=0,backupEpoch=0;
const isBunker=id=>/^FM-1_710000[12]$/.test(id);
let pending;try{pending=JSON.parse(localStorage.getItem('bunker-pending')||'null');if(['wolf','rc1','amb','stock'].includes(pending?.target))target=pending.target;}catch{}
// An unfinished RC1 operation must resume with its original package.
if(pending?.target==='wolf' && pending.hash==='eb0b0924a9da226b53f0bfcb0bfed7bb47763ab237eab03b79c8f7311d1fe6d4')target='rc1';
document.querySelectorAll('[name=target]').forEach(e=>e.checked=e.value===target);
if(['rc1','amb'].includes(target))$('legacyOptions')?.setAttribute('open','');
function log(s){logLines.push(new Date().toISOString()+' '+s);if(logLines.length>500)logLines.shift();$('log').textContent=logLines.join('\n');}
function refresh(){ $('backupButton').disabled=busy||!connected||!isBunker(detected); $('restoreButton').disabled=busy||!connected||!isBunker(detected)||!archive||!$('restoreReady').checked; $('backupFile').disabled=busy; $('restoreReady').disabled=busy; const valid=!!packs[target];$('install').disabled=busy||!connected||!valid||!$('ready').checked;$('connect').disabled=busy;$('stockFile').disabled=busy;$('ready').disabled=busy;document.querySelectorAll('[name=target]').forEach(e=>e.disabled=busy);$('stockBox').hidden=target!=='stock';$('packageStatus').textContent=valid?'SHA-256 verified · '+packs[target].product+' · '+packs[target].raw.length+' bytes':'Target package is not available yet.';}
async function sha(bytes){return [...new Uint8Array(await crypto.subtle.digest('SHA-256',bytes))].map(x=>x.toString(16).padStart(2,'0')).join('');}
export async function checkedPackage(raw,hash,product){if(raw.length<960||raw.length>2*1024*1024)throw Error('Invalid package size.');if(await sha(raw)!==hash)throw Error('Package checksum mismatch. Nothing will be written.');const id=productOf(raw);if(!/^FM-1_\d+$/.test(id)||product&&id!==product)throw Error('Wrong package identity.');return {raw,product:id,image:logicalImage(raw),hash};}
async function midi(){if(!navigator.requestMIDIAccess)throw Error('Open this HTTPS page in desktop Chrome or Edge.');if(!access)access=await navigator.requestMIDIAccess({sysex:true});return access;}
async function exclusive(fn){if(!navigator.locks)throw Error('This browser does not support the installation lock. Use current desktop Chrome.');return navigator.locks.request('bunker-evolved-fm1-update',{ifAvailable:true},async lock=>{if(!lock)throw Error('Another editor or installer tab from this site is connected. Disconnect it first.');return fn();});}
function oneDevice(a){const inputs=[...a.inputs.values()].filter(p=>p.state!=='disconnected'&&/fm-1|felucca|ota|composite|sinco|usb-midi/i.test(p.name||''));if(inputs.length!==1)throw Error('Connect exactly one FM-1. Candidate inputs found: '+inputs.length);}
async function identify(){const a=await midi();oneDevice(a);const up=new Updater(a,log);const d=await up.find(id=>/^(ota-)?FM-1$/i.test(id.model));if(!d)throw Error('No matching device response. Close other MIDI apps and check the cable.');const text=d.id.text;d.link.close();return text;}
$('connect').onclick=async()=>{if(busy)return;busy=true;refresh();try{await exclusive(async()=>{const id=await identify();connected=true;detected=id;$('backupStatus').textContent=isBunker(id)?'Bunker detected. Stop playback and recording before backup or restore.':'This firmware uses a different music format. Use its own backup tools first.';$('device').textContent='Detected: '+id;log('Identity: '+id+' (read-only query; no flash)');});}catch(e){connected=false;$('device').textContent=e.message;log(e.message);}finally{busy=false;refresh();}};
$('ready').onchange=refresh;document.querySelectorAll('[name=target]').forEach(e=>e.onchange=()=>{target=e.value;$('ready').checked=false;refresh();});
$('stockFile').onchange=async e=>{delete packs.stock;refresh();try{const epoch=++stockEpoch;const f=e.target.files[0];if(!f)return;if(f.size>2*1024*1024)throw Error('File too large.');const checked=await checkedPackage(new Uint8Array(await f.arrayBuffer()),STOCK_SHA);if(epoch!==stockEpoch)return;packs.stock=checked;$('stockStatus').textContent='Original V15 verified: '+packs.stock.product;}catch(e){$('stockStatus').textContent=e.message;}refresh();};
const messages={start:'Device confirmed; requesting package.',verify:'Stage 1/2: preparing the update loader.',loader:'Waiting for the update loader…',write:'Stage 2/2: writing firmware. Keep power and USB connected.',reboot:'Writing complete; waiting for reboot and checking identity…',done:'Installation and final device identity confirmed.'};
function step(k,n){$('status').textContent=messages[k]||k;if(k==='verify')$('progress').value=Math.min(10,n/74*10);if(k==='write')$('progress').value=10+Math.min(84,n/1167*84);if(k==='reboot')$('progress').value=95;if(k==='done')$('progress').value=100;if(!['verify','write'].includes(k)||n%100===0)log(k+' '+(n??''));}
const errors={notfound:'FM-1 not found.',model:'Device model does not match.',lost:'USB disconnected. Keep the device powered and read the recovery guide.',stopped:'Transfer stopped. Success has not been confirmed.',noloader:'Update loader not found. Success has not been confirmed.',noreturn:'Reboot not confirmed. Save the log.',mismatch:'Device reports a different firmware identity. Success has not been confirmed.',badreq:'Invalid data request; transfer stopped.'};
$('install').onclick=async()=>{if(busy||!connected||!packs[target]||!$('ready').checked)return;const selected=target,pkg=packs[selected];busy=true;refresh();let wake;try{await exclusive(async()=>{const a=await midi();oneDevice(a);await checkedPackage(pkg.raw,pkg.hash,pkg.product);try{wake=await navigator.wakeLock?.request('screen');}catch{}try{localStorage.setItem('bunker-pending',JSON.stringify({target:selected,hash:pkg.hash}));}catch{}log('START '+selected+' '+pkg.product+' SHA256 '+pkg.hash);$('progress').value=0;const up=new Updater(a,log);const loader=await up.find(id=>/^ota-FM-1$/i.test(id.model));if(loader){loader.link.close();log('Loader active: restarting the writing phase.');if(!await up.resume(pkg.image,step))throw Error('Loader write did not complete.');step('reboot');const back=await up.waitFor(id=>!/^ota-/i.test(id.model),40000);if(!back)throw Error('No application identity after recovery.');const id=back.id.text;back.link.close();if(id!==pkg.product)throw Error('Unexpected identity after recovery: '+id);step('done',id);}else await up.install(pkg.image,pkg.product,step);detected=pkg.product;$('device').textContent='Confirmed: '+pkg.product;try{localStorage.removeItem('bunker-pending');}catch{}pending=null;log('DONE: identity confirmed. Check audio and controls on the device.');});}catch(e){$('status').textContent=selected==='stock'&&e.code==='mismatch'?'Manufacturer package transferred; device reports '+e.detail+'. Check the original startup screen: identity differs from the package, so restoration is not automatically confirmed.':(errors[e.code]||e.message)+(e.detail?' '+e.detail:'');log('ERROR '+(e.code||'')+' '+e.message);connected=false;}finally{try{await wake?.release();}catch{}busy=false;$('ready').checked=false;refresh();}};

function downloadJSON(file,name){const url=URL.createObjectURL(new Blob([JSON.stringify(file,null,2)],{type:'application/json'}));const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
async function musicConnection(){const a=await midi();oneDevice(a);const up=new Updater(a,log);const d=await up.find(id=>id.model==='FM-1');if(!d)throw Error('No running FM-1 application found.');const id=d.id.text;const input=d.link.input,output=d.link.output;d.link.close();if(!isBunker(id))throw Error('Music backup and restore on this page require a compatible Bunker Evolved build.');return {link:new BackupConnection(input,output),id};}
$('backupButton').onclick=async()=>{if(busy||!connected||!isBunker(detected))return;busy=true;refresh();let link;try{await exclusive(async()=>{const d=await musicConnection();link=d.link;const file=await captureBackup((r,o)=>link.request(r,o),d.id,(n,total)=>{$('backupStatus').textContent='Reading music archive: '+Math.round(n/Math.max(total,1)*100)+'%';});downloadJSON(file,'Bunker-Evolved-Music-'+new Date().toISOString().slice(0,10)+'.json');$('backupStatus').textContent='Archive verified and download requested. Check that the file is saved on your computer before changing firmware.';log('MUSIC BACKUP: CRC-checked archive downloaded.');});}catch(e){$('backupStatus').textContent=e.message;log('BACKUP ERROR '+e.message);}finally{link?.close();busy=false;refresh();}};
$('backupFile').onchange=async e=>{archive=null;$('restoreReady').checked=false;const epoch=++backupEpoch;refresh();try{const f=e.target.files[0];if(!f)return;if(f.size>1024*1024)throw Error('Music archive too large.');const checked=readBackup(await f.text());if(epoch!==backupEpoch)return;if(!isBunker(checked.firmware))throw Error('This is not a compatible Bunker Evolved archive made by this installer.');archive=checked;$('backupStatus').textContent='All archive checksums verified. '+checked.firmware+' — choose Restore only if you want to replace device music.';}catch(e){$('backupStatus').textContent=e.message;}refresh();};
$('restoreReady').onchange=refresh;
$('restoreButton').onclick=async()=>{if(busy||!connected||!archive||!isBunker(detected)||!$('restoreReady').checked)return;const selected=archive;busy=true;refresh();let link;try{await exclusive(async()=>{const d=await musicConnection();link=d.link;await restoreBackup((r,o)=>link.request(r,o),selected,(n,total)=>{$('backupStatus').textContent='Restoring music: '+Math.round(n/Math.max(total,1)*100)+'%';});$('backupStatus').textContent='Music archive restored. Check the project and sounds on the FM-1.';log('MUSIC RESTORE: all objects acknowledged.');});}catch(e){$('backupStatus').textContent='Restore not complete; some objects may already be replaced. '+e.message;log('RESTORE ERROR '+e.message);}finally{link?.close();busy=false;$('restoreReady').checked=false;refresh();}};
window.addEventListener('beforeunload',e=>{if(busy){e.preventDefault();e.returnValue='';}});
$('download').onclick=()=>{const url=URL.createObjectURL(new Blob([logLines.join('\n')],{type:'text/plain'}));const a=document.createElement('a');a.href=url;a.download='Bunker-Evolved-Install-Log.txt';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);};
(async()=>{try{const res=await fetch('manifest.json',{cache:'no-store'});if(!res.ok)throw Error('Package list unavailable.');manifest=await res.json();if(pending)log('Previous operation was not confirmed: '+pending.target+'. Target selected again.');for(const name of ['wolf','rc1','amb']){try{const m=manifest[name],r=await fetch(m.file,{cache:'no-store'});if(!r.ok)throw Error(name+': download failed.');packs[name]=await checkedPackage(new Uint8Array(await r.arrayBuffer()),m.sha256,m.product);log(name+' checked locally: '+m.product);}catch(e){log('PACKAGE ERROR '+e.message);if(name===target)$('status').textContent=e.message;}refresh();}}catch(e){$('status').textContent=e.message;log(e.message);}refresh();})();
